static String chipId() {
  uint64_t mac = ESP.getEfuseMac();
  char buf[13];
  snprintf(buf, sizeof(buf), "%04X%08X", (uint16_t)(mac >> 32), (uint32_t)mac);
  return String(buf);
}

static String upper(String s) { s.trim(); s.toUpperCase(); return s; }
static String lower(String s) { s.trim(); s.toLowerCase(); return s; }

static String sha256Hex(const String& input) {
  uint8_t digest[32];
  mbedtls_sha256_context ctx;
  mbedtls_sha256_init(&ctx);
  mbedtls_sha256_starts_ret(&ctx, 0);
  mbedtls_sha256_update_ret(&ctx, (const unsigned char*)input.c_str(), input.length());
  mbedtls_sha256_finish_ret(&ctx, digest);
  mbedtls_sha256_free(&ctx);
  char hex[65];
  for (int i = 0; i < 32; i++) {
    snprintf(hex + (i * 2), 3, "%02x", digest[i]);
  }
  hex[64] = '\0';
  return String(hex);
}

static String jsonStr(JsonVariantConst v, const String& def = "") {
  if (v.isNull()) return def;
  String s = v.as<String>();
  return s.length() ? s : def;
}

static String jsonString(const JsonDocument& doc) {
  String out;
  out.reserve(measureJson(doc) + 16);
  serializeJson(doc, out);
  return out;
}

// Pick a heap-safe capacity for ArduinoJson so we never crash when heap is tight
static size_t safeJsonCap(size_t ideal, size_t minCap = 8192) {
  size_t maxBlk = ESP.getMaxAllocHeap();
  if (maxBlk > ideal + 12288) return ideal;
  if (maxBlk > 20480) return max(minCap, maxBlk - 12288);
  return minCap;
}

static bool validDate(const String& d) {
  if (d.length() != 10 || d[4] != '-' || d[7] != '-') return false;
  for (int i = 0; i < 10; i++) {
    if (i == 4 || i == 7) continue;
    if (!isDigit(d[i])) return false;
  }
  int y = d.substring(0, 4).toInt();
  int m = d.substring(5, 7).toInt();
  int day = d.substring(8, 10).toInt();
  return y >= 2020 && y <= 2099 && m >= 1 && m <= 12 && day >= 1 && day <= 31;
}

static String statusText(AStatus st) {
  switch (st) {
    case AStatus::PRESENT: return "Present";
    case AStatus::LATE: return "Late";
    case AStatus::ABSENT: return "Absent";
    case AStatus::LEAVE: return "Leave";
    case AStatus::HALF: return "Half Day";
    default: return "Not marked";
  }
}

static AStatus parseStatus(String s) {
  s = lower(s);
  if (s == "present") return AStatus::PRESENT;
  if (s == "late") return AStatus::LATE;
  if (s == "absent") return AStatus::ABSENT;
  if (s == "leave") return AStatus::LEAVE;
  if (s == "half" || s == "half day" || s == "half-day") return AStatus::HALF;
  return AStatus::NONE;
}

static uint8_t percentage(const Student& s) {
  uint32_t tot = (uint32_t)s.present + s.late + s.absent + s.leave + s.half;
  if (!tot) return 0;
  uint32_t weighted = (uint32_t)s.present * 2 + (uint32_t)s.late * 2 + (uint32_t)s.leave * 2 + (uint32_t)s.half;
  uint32_t pct = (weighted * 100UL + tot) / (tot * 2UL);
  return (uint8_t)constrain((int)pct, 0, 100);
}

namespace Clock {
static Preferences prefs;
static uint32_t baseEpoch = 1762939800UL; // Nov 2025/2026 baseline until NTP or browser syncs
static uint32_t baseMillis = 0, lastPersistAt = 0;
static bool syncedFlag = false;

static uint32_t now() {
  time_t tv = time(nullptr);
  if (tv > 1700000000L) return (uint32_t)tv;
  return baseEpoch + (millis() - baseMillis) / 1000UL;
}

static bool isSane() {
  return time(nullptr) > 1700000000L || syncedFlag;
}

static void epochToIstTm(uint32_t ep, struct tm& ti) {
  time_t istSec = (time_t)ep + TZ_OFFSET_SEC;
  gmtime_r(&istSec, &ti);
}

static void begin() {
  setenv("TZ", "IST-5:30", 1);
  tzset();
  prefs.begin("clock", true);
  uint32_t saved = prefs.getULong("epoch", 0);
  prefs.end();
  if (saved > 1700000000UL) {
    baseEpoch = saved;
    syncedFlag = true;
    struct timeval tv = { (time_t)saved, 0 };
    settimeofday(&tv, nullptr);
  }
  baseMillis = millis();
}

static void sync(uint32_t e) {
  if (e <= 1700000000UL) return;
  baseEpoch = e;
  baseMillis = millis();
  syncedFlag = true;
  struct timeval tv = { (time_t)e, 0 };
  settimeofday(&tv, nullptr);
  setenv("TZ", "IST-5:30", 1);
  tzset();
  prefs.begin("clock", false);
  prefs.putULong("epoch", e);
  prefs.end();
  lastPersistAt = millis();
}

// Parse HTTP Date header ("Fri, 13 Nov 2026 17:35:30 GMT") to Unix epoch so Supabase HTTPS responses sync IST clock even when UDP NTP is blocked
static void syncFromHttpDate(const String& httpDate) {
  if (httpDate.length() < 20) return;
  int day = 0, year = 0, hr = 0, mn = 0, sc = 0;
  char monStr[4] = {0};
  int comma = httpDate.indexOf(',');
  String sub = (comma >= 0) ? httpDate.substring(comma + 1) : httpDate;
  sub.trim();
  if (sscanf(sub.c_str(), "%d %3s %d %d:%d:%d", &day, monStr, &year, &hr, &mn, &sc) != 6) return;
  if (year < 2025 || year > 2099 || day < 1 || day > 31) return;
  static const char* kMons[] = { "Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec" };
  int mon = -1;
  for (int i = 0; i < 12; i++) {
    if (strncasecmp(monStr, kMons[i], 3) == 0) { mon = i; break; }
  }
  if (mon < 0) return;
  static const int mdays[] = { 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31 };
  uint32_t days = 0;
  for (int y = 1970; y < year; y++) {
    bool leap = (y % 4 == 0 && y % 100 != 0) || (y % 400 == 0);
    days += leap ? 366UL : 365UL;
  }
  bool curLeap = (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0);
  for (int m = 0; m < mon; m++) {
    days += (uint32_t)mdays[m] + (m == 1 && curLeap ? 1UL : 0UL);
  }
  days += (uint32_t)(day - 1);
  uint32_t ep = days * 86400UL + (uint32_t)hr * 3600UL + (uint32_t)mn * 60UL + (uint32_t)sc;
  if (ep > 1700000000UL && (!syncedFlag || labs((long)ep - (long)now()) > 60L)) {
    sync(ep);
  }
}

static void service() {
  time_t tv = time(nullptr);
  if (tv > 1700000000L) {
    syncedFlag = true;
    if (millis() - lastPersistAt > 900000UL) {
      lastPersistAt = millis();
      prefs.begin("clock", false);
      prefs.putULong("epoch", (uint32_t)tv);
      prefs.end();
    }
  }
}
}

static uint32_t nowEpoch() { return Clock::now(); }
static bool saneClock() { return Clock::isSane(); }

// Deterministic IST (UTC+5:30) date and time helpers - never uses UTC
static String dateNow() {
  struct tm ti = {};
  Clock::epochToIstTm(nowEpoch(), ti);
  char b[16];
  snprintf(b, sizeof(b), "%04d-%02d-%02d", ti.tm_year + 1900, ti.tm_mon + 1, ti.tm_mday);
  return String(b);
}

static String timeNow() {
  struct tm ti = {};
  Clock::epochToIstTm(nowEpoch(), ti);
  char b[12];
  snprintf(b, sizeof(b), "%02d:%02d:%02d", ti.tm_hour, ti.tm_min, ti.tm_sec);
  return String(b);
}

static int currentIstMinutes() {
  struct tm ti = {};
  Clock::epochToIstTm(nowEpoch(), ti);
  return ti.tm_hour * 60 + ti.tm_min;
}

// 12-hour time string for LCD ("10:42 AM") or "--:--" when clock not synced (never "00:00")
static String lcdTime12h() {
  if (!saneClock()) return "--:--";
  struct tm ti = {};
  Clock::epochToIstTm(nowEpoch(), ti);
  int h12 = ti.tm_hour % 12;
  if (h12 == 0) h12 = 12;
  const char* ampm = (ti.tm_hour >= 12) ? "PM" : "AM";
  char b[16];
  snprintf(b, sizeof(b), "%02d:%02d %s", h12, ti.tm_min, ampm);
  return String(b);
}

// Date string with 3-letter month for LCD ("Mon 10 Nov 2026") or "--/--/----" when unsynced
static String lcdDateDmy() {
  if (!saneClock()) return "--/--/----";
  static const char* kDows[] = { "Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat" };
  static const char* kMons[] = { "Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec" };
  struct tm ti = {};
  Clock::epochToIstTm(nowEpoch(), ti);
  const char* dow = kDows[constrain(ti.tm_wday, 0, 6)];
  const char* mon = kMons[constrain(ti.tm_mon, 0, 11)];
  char b[20];
  snprintf(b, sizeof(b), "%s %02d %s %04d", dow, ti.tm_mday, mon, ti.tm_year + 1900);
  return String(b);
}

namespace Lock {
static Preferences prefs;
static String pass = "", unlockedOn = "", rxLine = "";

static void begin() {
  prefs.begin("esp-lock", true);
  pass = prefs.getString("pass", "");
  unlockedOn = prefs.getString("day", "");
  prefs.end();
}

static bool isSet() { return pass.length() > 0; }
static bool unlockedToday() { return !isSet() || unlockedOn == dateNow(); }

static void setPass(const String& p) {
  pass = p;
  unlockedOn = dateNow();
  prefs.begin("esp-lock", false);
  prefs.putString("pass", pass);
  prefs.putString("day", unlockedOn);
  prefs.end();
}

static void removePass() {
  pass = "";
  unlockedOn = "";
  prefs.begin("esp-lock", false);
  prefs.clear();
  prefs.end();
}

static void service() {
  while (Serial.available()) {
    char c = (char)Serial.read();
    if (c == '\n' || c == '\r') {
      rxLine.trim();
      if (rxLine.length()) {
        if (!isSet() || rxLine == pass || rxLine == ADMIN_PASS) {
          unlockedOn = dateNow();
          prefs.begin("esp-lock", false);
          prefs.putString("day", unlockedOn);
          prefs.end();
          Serial.println("[LOCK] serial console unlocked for " + unlockedOn);
        } else {
          Serial.println("[LOCK] locked - enter serial password");
        }
        rxLine = "";
      }
    } else if (rxLine.length() < 96) {
      rxLine += c;
    }
  }
}
}

namespace BootGuard {
static Preferences prefs;
static bool panicked = false, safeFlag = false, cleared = false;
static uint8_t crashes = 0;
static int resetCode = 0;

static const char* reasonText(int r) {
  switch (r) {
    case ESP_RST_POWERON: return "power-on";
    case ESP_RST_SW: return "software";
    case ESP_RST_PANIC: return "exception-panic";
    case ESP_RST_INT_WDT: return "interrupt-wdt";
    case ESP_RST_TASK_WDT: return "task-wdt";
    case ESP_RST_WDT: return "other-wdt";
    case ESP_RST_BROWNOUT: return "brownout";
    default: return "normal";
  }
}

static void begin() {
  resetCode = (int)esp_reset_reason();
  panicked = (resetCode == ESP_RST_PANIC || resetCode == ESP_RST_INT_WDT || resetCode == ESP_RST_TASK_WDT || resetCode == ESP_RST_WDT);
  prefs.begin("boot-guard", false);
  crashes = prefs.getUChar("crashes", 0);
  if (panicked) {
    if (crashes < 250) crashes++;
    prefs.putUChar("crashes", crashes);
  }
  safeFlag = (crashes >= 3);
  prefs.end();
}

static bool recentPanic() { return panicked; }
static bool safe() { return safeFlag; }

static void service() {
  if (!cleared && millis() > 45000UL) {
    cleared = true;
    crashes = 0;
    safeFlag = false;
    prefs.begin("boot-guard", false);
    prefs.putUChar("crashes", 0);
    prefs.end();
  }
}

static void toJson(JsonObject o) {
  o["resetReason"] = reasonText(resetCode);
  o["recentPanic"] = panicked;
  o["crashCount"] = crashes;
  o["safeMode"] = safeFlag;
  o["stable"] = cleared;
}
}

