static bool studentCacheDirty = false;
static uint32_t dirtySince = 0;
static bool fsReady = false;
static bool freshWiped = false;

static void ensureFs() {
  if (!fsReady) {
    fsReady = LittleFS.begin(true);
  }
}

static void markDirty(bool fromCloud = false) {
  studentCacheDirty = true;
  if (!dirtySince) dirtySince = millis();
  generation++;
  if (!fromCloud) lastLocalMutationAt = millis();
}

static void markCloudAck() {
  studentCacheDirty = true;
  if (!dirtySince) dirtySince = millis();
}

static bool allDigits(const String& s) {
  if (!s.length()) return false;
  for (size_t i = 0; i < s.length(); i++) if (!isDigit(s[i])) return false;
  return true;
}

static const char* ID_COUNTER_PATH = "/state_id_counter.json";

// Load persistent sequential student password counter (starts at 1001, never derived from students.size())
static uint32_t loadPasswordCounter() {
  ensureFs();
  uint32_t best = (config.nextStudentPassword >= 1001UL) ? config.nextStudentPassword : 1001UL;
  Preferences idp;
  idp.begin("astro-id", true);
  uint32_t nvsVal = idp.getULong("nextPw", 1001UL);
  idp.end();
  if (nvsVal > best) best = nvsVal;
  if (fsReady && LittleFS.exists(ID_COUNTER_PATH)) {
    File cf = LittleFS.open(ID_COUNTER_PATH, "r");
    if (cf) {
      StaticJsonDocument<128> cd;
      if (!deserializeJson(cd, cf)) {
        uint32_t fVal = (uint32_t)(cd["next"] | 1001UL);
        if (fVal > best) best = fVal;
      }
      cf.close();
    }
  }
  config.nextStudentPassword = best;
  return best;
}

// Atomically persist next_student_password across LittleFS (/state_id_counter.json), NVS Preferences, and Config
static void savePasswordCounter(uint32_t nextVal) {
  if (nextVal < 1001UL) nextVal = 1001UL;
  config.nextStudentPassword = nextVal;
  Preferences idp;
  idp.begin("astro-id", false);
  idp.putULong("nextPw", nextVal);
  idp.end();
  ensureFs();
  if (fsReady) {
    File tf = LittleFS.open("/state_id_counter.tmp", "w");
    if (tf) {
      StaticJsonDocument<128> cd;
      cd["next"] = nextVal;
      serializeJson(cd, tf);
      tf.flush();
      tf.close();
      LittleFS.remove(ID_COUNTER_PATH);
      LittleFS.rename("/state_id_counter.tmp", ID_COUNTER_PATH);
    }
  }
}

// Reset persistent password counter to 1001 (ONLY called during Factory Reset step 3f)
static void resetPasswordCounterTo1001() {
  savePasswordCounter(1001UL);
}

// Peek next sequential student password without incrementing (NEVER derived from current student count)
static String nextStudentNumber() {
  uint32_t cur = loadPasswordCounter();
  return String(cur);
}

// Reserve and atomically increment the persistent sequential student password (1001, 1002, 1003, ...)
static uint32_t reserveNextStudentPassword() {
  uint32_t issued = loadPasswordCounter();
  savePasswordCounter(issued + 1UL);
  return issued;
}

// Roll back a reserved password number if Supabase student creation fails
static void rollbackReservedStudentPassword(uint32_t reservedSeq) {
  if (config.nextStudentPassword == reservedSeq + 1UL && reservedSeq >= 1001UL) {
    savePasswordCounter(reservedSeq);
  }
}

// Resolve unique Student ID = student's name (trimmed, case preserved; appends " 2", " 3" on collision)
static String resolveUniqueStudentNameId(const String& rawName, const String& excludeRfid = "") {
  String baseName = rawName;
  baseName.trim();
  if (!baseName.length()) baseName = "Student";
  String excl = upper(excludeRfid);
  for (uint16_t suffix = 1; suffix < 1000; suffix++) {
    String candidate = (suffix == 1) ? baseName : (baseName + " " + String(suffix));
    bool collision = false;
    for (const auto& s : students) {
      if (excl.length() && s.rfid == excl) continue;
      if (s.studentId.equalsIgnoreCase(candidate) || (suffix == 1 && s.name.equalsIgnoreCase(candidate) && s.studentId.equalsIgnoreCase(s.name))) {
        collision = true;
        break;
      }
    }
    if (!collision) return candidate;
  }
  return baseName + " " + String(millis() % 10000UL);
}

// Backward-compatible wrapper returning unique Name ID
static String generateStudentId(const String& nameHint = "Student", const String& excludeRfid = "") {
  return resolveUniqueStudentNameId(nameHint, excludeRfid);
}

static Student* student(const String& rfid) {
  String k = upper(rfid);
  if (!k.length()) return nullptr;
  for (auto& s : students) {
    if (s.rfid == k || s.studentId.equalsIgnoreCase(k)) return &s;
  }
  return nullptr;
}

static Student* loginStudent(const String& key) {
  String q = key; q.trim();
  if (!q.length()) return nullptr;
  for (auto& s : students) {
    if (s.name.equalsIgnoreCase(q) || s.rfid.equalsIgnoreCase(q) || s.roll.equalsIgnoreCase(q) || s.studentId.equalsIgnoreCase(q)) return &s;
    if (s.email.length() && s.email.equalsIgnoreCase(q)) return &s;
  }
  String ql = lower(q);
  for (auto& s : students) {
    int sp = s.name.indexOf(' ');
    String first = sp > 0 ? s.name.substring(0, sp) : s.name;
    if (first.equalsIgnoreCase(ql)) return &s;
  }
  return nullptr;
}

static String generateUniqueRfid() {
  for (int attempt = 0; attempt < 64; attempt++) {
    uint32_t r = esp_random() & 0xFFFFFFUL;
    char buf[10];
    snprintf(buf, sizeof(buf), "A5%06X", (unsigned int)r);
    String cand(buf);
    if (cand == CARD_ADMIN || cand == CARD_GUARDIAN || cand == CARD_DELETE) continue;
    if (!student(cand)) return cand;
  }
  return "A5" + String(millis() & 0xFFFFFFUL, HEX);
}

static int hmToMins(const String& hm, int fallback = 540) {
  if (hm.length() < 5 || hm[2] != ':') return fallback;
  int h = hm.substring(0, 2).toInt();
  int m = hm.substring(3, 5).toInt();
  if (h < 0 || h > 23 || m < 0 || m > 59) return fallback;
  return h * 60 + m;
}

static String minsToHm(int totalMins) {
  int m = ((totalMins % 1440) + 1440) % 1440;
  char b[8];
  snprintf(b, sizeof(b), "%02d:%02d", m / 60, m % 60);
  return String(b);
}

static int parseTimingVariant(JsonVariantConst v, const String& startStr, int defVal, int lo, int hi) {
  if (v.isNull()) return defVal;
  String s = v.as<String>();
  s.trim();
  if (!s.length()) return defVal;
  if (s.indexOf(':') > 0) {
    int cut = hmToMins(s, -1);
    int st = hmToMins(startStr, 540);
    if (cut < 0) return defVal;
    int diff = cut - st;
    if (diff < 0) diff += 1440;
    return constrain(diff, lo, hi);
  }
  return constrain((int)s.toInt(), lo, hi);
}

// Parse either HH:MM or minutes-since-midnight or relative offset into absolute minutes-since-midnight (IST)
static uint16_t parseCutoffMinutes(JsonVariantConst v, const String& startStr, uint16_t defAbsMin) {
  if (v.isNull()) return defAbsMin;
  String s = v.as<String>();
  s.trim();
  if (!s.length()) return defAbsMin;
  if (s.indexOf(':') > 0) {
    int cut = hmToMins(s, -1);
    if (cut >= 0 && cut < 1440) return (uint16_t)cut;
    return defAbsMin;
  }
  int num = s.toInt();
  int st = hmToMins(startStr, 540);
  if (num >= 300 && num < 1440) return (uint16_t)num; // Already minutes-since-midnight
  return (uint16_t)constrain(st + constrain(num, 0, 480), 0, 1439);
}

static void syncTimingCutoffsFromRelative() {
  int st = hmToMins(config.start, 540);
  config.lateAfterMin = (uint16_t)constrain(st + (int)config.lateAfter, 0, 1439);
  config.absentAfterMin = (uint16_t)constrain(st + (int)config.absentAfter, (int)config.lateAfterMin + 1, 1439);
}

static void syncTimingRelativeFromCutoffs() {
  int st = hmToMins(config.start, 540);
  int laDiff = (int)config.lateAfterMin - st;
  if (laDiff < 0) laDiff = 0;
  int abDiff = (int)config.absentAfterMin - st;
  if (abDiff < laDiff + 1) abDiff = laDiff + 1;
  config.lateAfter = (uint16_t)constrain(laDiff, 0, 240);
  config.absentAfter = (uint16_t)constrain(abDiff, 1, 480);
}

static bool isLeap(int y) { return (y % 4 == 0 && y % 100 != 0) || (y % 400 == 0); }

static String nextDateStr(const String& d) {
  if (!validDate(d)) return dateNow();
  int y = d.substring(0, 4).toInt();
  int m = d.substring(5, 7).toInt();
  int day = d.substring(8, 10).toInt();
  static const int mdays[] = { 0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31 };
  int dim = mdays[constrain(m, 1, 12)] + (m == 2 && isLeap(y) ? 1 : 0);
  day++;
  if (day > dim) { day = 1; m++; if (m > 12) { m = 1; y++; } }
  char b[16];
  snprintf(b, sizeof(b), "%04d-%02d-%02d", y, m, day);
  return String(b);
}

static int dayOfWeek(const String& d) {
  if (!validDate(d)) return -1;
  int y = d.substring(0, 4).toInt();
  int m = d.substring(5, 7).toInt();
  int day = d.substring(8, 10).toInt();
  static const int t[] = { 0, 3, 2, 5, 0, 3, 5, 1, 4, 6, 2, 4 };
  if (m < 3) y -= 1;
  return (y + y / 4 - y / 100 + y / 400 + t[m - 1] + day) % 7;
}

static bool isHolidayDate(const String& d) {
  if (std::find(holidays.begin(), holidays.end(), d) != holidays.end()) return true;
  if (config.weeklyOff) {
    int dow = dayOfWeek(d);
    if (dow >= 0 && dow == (int)config.weeklyOffDay) return true;
  }
  return false;
}

// Compute status strictly in IST (Asia/Kolkata, UTC+5:30) against lateAfterMin / absentAfterMin
static AStatus calculateStatus(const String& hm = "") {
  int currentMin = hm.length() >= 5 ? hmToMins(hm, currentIstMinutes()) : currentIstMinutes();
  if (currentMin <= (int)config.lateAfterMin) return AStatus::PRESENT;
  if (currentMin <= (int)config.absentAfterMin) return AStatus::LATE;
  return AStatus::ABSENT;
}

static Record* record(const String& rfid, const String& date) {
  String k = upper(rfid);
  for (auto& r : records) if (r.rfid == k && r.date == date) return &r;
  return nullptr;
}

static PeriodRecord* periodRecord(const String& rfid, const String& date, uint8_t period) {
  String k = upper(rfid);
  for (auto& p : periodMarks) if (p.rfid == k && p.date == date && p.period == period) return &p;
  return nullptr;
}

static void trimNotices(size_t maxCount) {
  while (notices.size() > maxCount) {
    size_t killIdx = 0;
    for (size_t i = 0; i < notices.size(); i++) if (!notices[i].pinned) { killIdx = i; break; }
    notices.erase(notices.begin() + killIdx);
  }
}

static void trimDms(size_t maxCount) {
  while (dms.size() > maxCount) {
    dms.erase(dms.begin());
  }
}

static void recount(Student& s) {
  s.present = s.late = s.absent = s.leave = s.half = s.streak = 0;
  s.today = AStatus::NONE;
  s.lastDate = "";
  s.lastTime = "";
  String td = dateNow();
  std::vector<String> days;
  days.reserve(64);
  for (auto& r : records) {
    if (r.rfid != s.rfid || !validDate(r.date)) continue;
    if (std::find(holidays.begin(), holidays.end(), r.date) != holidays.end()) continue;
    if (std::find(days.begin(), days.end(), r.date) == days.end()) days.push_back(r.date);
  }
  for (auto& l : leaves) {
    if (l.rfid != s.rfid || l.status != "approved" || !validDate(l.from) || !validDate(l.to)) continue;
    String cur = l.from;
    for (int g = 0; g < 120 && cur <= l.to; g++) {
      if (std::find(holidays.begin(), holidays.end(), cur) == holidays.end()) {
        if (std::find(days.begin(), days.end(), cur) == days.end()) days.push_back(cur);
      }
      cur = nextDateStr(cur);
    }
  }
  std::sort(days.begin(), days.end());
  uint16_t curStreak = 0;
  for (auto& d : days) {
    Record* r = record(s.rfid, d);
    AStatus st = r ? r->status : AStatus::NONE;
    for (auto& l : leaves) {
      if (l.rfid == s.rfid && l.status == "approved" && d >= l.from && d <= l.to) {
        st = AStatus::LEAVE;
        break;
      }
    }
    if (st == AStatus::PRESENT) { s.present++; curStreak++; }
    else if (st == AStatus::LATE) { s.late++; curStreak++; }
    else if (st == AStatus::LEAVE) { s.leave++; curStreak++; }
    else if (st == AStatus::HALF) { s.half++; curStreak++; }
    else if (st == AStatus::ABSENT) { s.absent++; curStreak = 0; }
    if (r && r->time.length() && d >= s.lastDate) {
      s.lastDate = d;
      s.lastTime = r->time;
    }
    if (d == td) s.today = st;
  }
  s.streak = curStreak;
}

static void recountAll() {
  for (auto& s : students) recount(s);
}

static void stampCurrentPeriod(const String& rfid, const String& date, AStatus st, const String& hm) {
  int base = hmToMins(config.periodStart, 540);
  int curM = hmToMins(hm, -1);
  if (curM < 0) return;
  for (uint8_t p = 1; p <= config.periods; p++) {
    int pStart = base + (p - 1) * (int)config.periodLength + (p > config.lunchAfter ? (int)config.lunchLength : 0);
    int pEnd = pStart + (int)config.periodLength;
    if (curM >= pStart - 15 && curM <= pEnd) {
      PeriodRecord* pr = periodRecord(rfid, date, p);
      if (!pr) {
        if (periodMarks.size() >= MAX_PERIOD_RECORDS) periodMarks.erase(periodMarks.begin());
        PeriodRecord np;
        np.rfid = rfid; np.date = date; np.period = p;
        periodMarks.push_back(np);
        pr = &periodMarks.back();
      }
      pr->status = st;
      pr->time = hm;
      pr->clouded = false;
    }
  }
}

static Record* putRecord(const String& rfid, const String& date, AStatus st, const String& source, const String& tm = "") {
  String k = upper(rfid);
  Record* r = record(k, date);
  if (!r) {
    if (records.size() >= MAX_RECORDS) records.erase(records.begin());
    Record nr;
    nr.rfid = k;
    nr.date = date;
    records.push_back(nr);
    r = &records.back();
  }
  String cleanTm = tm.length() ? tm : (st == AStatus::ABSENT && source == "automatic" ? String("") : timeNow().substring(0, 5));
  r->status = st;
  r->time = cleanTm;
  r->source = source;
  r->epoch = nowEpoch();
  r->clouded = false;
  if ((source == "rfid" || source == "fingerprint") && cleanTm.length()) {
    stampCurrentPeriod(k, date, st, cleanTm);
  }
  Student* s = student(k);
  if (s) {
    s->clouded = false;
    recount(*s);
  }
  markDirty(false);
  return r;
}

static void addEvent(const String& rfid, const String& name, const String& type, const String& status, const String& msg, bool known, bool marked) {
  if (events.size() >= MAX_EVENTS) events.erase(events.begin());
  ScanEvent e;
  e.id = nextEvent++;
  e.rfid = upper(rfid);
  e.name = name;
  e.type = type;
  e.status = status;
  e.message = msg;
  e.date = dateNow();
  e.time = timeNow().substring(0, 5);
  e.known = known;
  e.marked = marked;
  e.clouded = false;
  events.push_back(e);
  markDirty(false);
}

static void addNotice(const String& msg) {
  Notice n;
  n.id = nextNotice++;
  n.title = "";
  n.body = "";
  n.message = msg;
  n.priority = "normal";
  n.audience = "All";
  n.date = dateNow();
  n.by = "System";
  n.status = "system";
  n.done = false;
  n.clouded = false;
  notices.push_back(n);
  trimNotices(MAX_NOTICES);
  markDirty(false);
}

static void clearAutoAbsentToday() {
  String td = dateNow();
  for (size_t i = 0; i < records.size(); ) {
    if (records[i].date == td && records[i].source == "automatic" && records[i].status == AStatus::ABSENT) {
      records.erase(records.begin() + i);
    } else i++;
  }
  recountAll();
}

static void recalcTodayScans() {
  String td = dateNow();
  for (auto& r : records) {
    if (r.date == td && (r.source == "rfid" || r.source == "fingerprint") && r.time.length() >= 5) {
      AStatus ns = calculateStatus(r.time.substring(0, 5));
      if (ns != r.status) {
        r.status = ns;
        r.clouded = false;
      }
    }
  }
  recountAll();
}

