  server.on("/api/student/goal", HTTP_POST, [] {
    if (!authed()) { error(401, "Login required"); return; }
    auto d = body();
    Student* s = Data::student(jsonStr(d["rfid"]));
    if (!s) { error(404, "Student not found"); return; }
    s->goal = constrain((int)(d["goal"] | 90), 0, 100);
    s->clouded = false;
    Data::markDirty(false);
    Data::save();
    Cloud::triggerSyncNow();
    ok("Goal updated");
  });

  server.on("/api/student/password", HTTP_POST, [] {
    if (!authed()) { error(401, "Login required"); return; }
    auto d = body();
    Student* s = Data::student(jsonStr(d["rfid"]));
    if (!s) { error(404, "Student not found"); return; }
    String old = jsonStr(d["current"]), nw = jsonStr(d["password"]);
    bool admin = d["admin"] | false;
    if (!admin && old != s->password && sha256Hex(old) != s->passwordHash) {
      error(401, "Current password is wrong");
      return;
    }
    if (nw.length() < 4) { error(400, "Password must have at least 4 characters"); return; }
    s->password = nw;
    s->passwordHash = sha256Hex(nw);
    s->mustChangePassword = false;
    s->clouded = false;
    Data::markDirty(false);
    Data::save();
    Cloud::rpcCreateStudent(*s);
    Cloud::triggerSyncNow();
    ok("Password changed");
  });

  // Non-blocking RFID registration endpoints (30s default window)
  server.on("/api/registration/start", HTTP_POST, [] {
    if (!authed()) { error(401, "Login required"); return; }
    if (!Hardware::rfidOk) Hardware::initRfid();
    if (!Hardware::rfidOk) { error(503, "RC522 RFID reader is not detected"); return; }
    auto d = body(512);
    uint32_t seconds = constrain((int)(d["seconds"] | 30), 20, 180);
    Hardware::rfid.PCD_AntennaOn();
    Hardware::registerUid = "";
    Hardware::registerRejectedUid = "";
    Hardware::registerMessage = "Reader ready. Tap one new RFID card.";
    Hardware::registerUntil = millis() + seconds * 1000UL;
    Hardware::showResult("Add student", "Tap new card", 3000);
    ok("RFID reader ready for student registration");
  });

  server.on("/api/registration/status", HTTP_GET, [] {
    if (!authed()) { error(401, "Login required"); return; }
    DynamicJsonDocument d(768);
    int32_t remaining = (int32_t)(Hardware::registerUntil - millis());
    bool active = remaining > 0;
    String capUid = Hardware::registerUid.length() ? Hardware::registerUid : Hardware::lastUnknownUid;
    d["ok"] = true;
    d["active"] = active;
    d["rfid"] = capUid;
    d["lastUnknownUid"] = Hardware::lastUnknownUid;
    d["captured"] = capUid.length() > 0;
    d["readerReady"] = Hardware::scanReady();
    d["readerState"] = Hardware::scanState();
    d["remainingSeconds"] = active ? (remaining + 999) / 1000 : 0;
    d["message"] = Hardware::registerMessage;
    d["rejectedRfid"] = Hardware::registerRejectedUid;
    json(d);
  });

  server.on("/api/registration/cancel", HTTP_POST, [] {
    if (!authed()) { error(401, "Login required"); return; }
    auto d = body(256);
    bool clr = d["clear"] | false;
    Hardware::registerUntil = 0;
    if (clr) { Hardware::registerUid = ""; Hardware::lastUnknownUid = ""; }
    Hardware::registerRejectedUid = "";
    Hardware::registerMessage = Hardware::registerUid.length() ? "Card captured. Complete the student form to save." : "Registration cancelled.";
    ok("Registration cancelled");
  });

  server.on("/api/attendance", HTTP_GET, [] {
    if (!authed()) { error(401, "Login required"); return; }
    String date = server.arg("date");
    if (!validDate(date)) date = dateNow();
    DynamicJsonDocument d(safeJsonCap(49152, 12288));
    d["ok"] = true;
    JsonArray a = d.createNestedArray("items");
    for (auto& s : Data::students) {
      Record* r = Data::record(s.rfid, date);
      JsonObject o = a.createNestedObject();
      o["rfid"] = s.rfid;
      o["student_id"] = s.studentId;
      o["name"] = s.name;
      o["roll"] = s.roll;
      o["status"] = r ? statusText(r->status) : "Absent";
      o["time"] = r ? r->time : "";
      o["method"] = r ? r->source : "rfid";
    }
    json(d);
  });

  server.on("/api/attendance/mark", HTTP_POST, [] {
    if (!authed()) { error(401, "Login required"); return; }
    auto d = body();
    String r = upper(jsonStr(d["rfid"], jsonStr(d["student_id"])));
    String date = jsonStr(d["date"], dateNow());
    String st = jsonStr(d["status"]);
    Student* stu = Data::student(r);
    if (!stu || !validDate(date) || parseStatus(st) == AStatus::NONE) { error(400, "Invalid student/date/status"); return; }
    Data::putRecord(stu->rfid, date, parseStatus(st), "manual");
    Data::addEvent(stu->rfid, stu->name, "manual", statusText(parseStatus(st)), "Attendance corrected", true, true);
    Data::save();
    Cloud::rpcMarkAttendance(stu->studentId, stu->rfid, date, statusText(parseStatus(st)), "rfid", timeNow().substring(0, 5));
    Cloud::triggerSyncNow();
    ok("Attendance marked");
  });

  server.on("/api/scan-events", HTTP_GET, [] {
    if (!authed()) { error(401, "Login required"); return; }
    uint32_t after = server.arg("after").toInt(), delivered = after, latest = Data::events.empty() ? 0 : Data::events.back().id;
    uint16_t limit = (uint16_t)constrain((int)server.arg("limit").toInt(), 1, 100);
    if (!server.hasArg("limit")) limit = 50;
    bool baseline = server.hasArg("baseline") && server.arg("baseline") != "0";
    DynamicJsonDocument d(safeJsonCap(32768, 8192));
    d["ok"] = true;
    JsonArray a = d.createNestedArray("items");
    if (!baseline) {
      for (auto& e : Data::events) {
        if (e.id > after && a.size() < limit) {
          JsonObject o = a.createNestedObject();
          o["id"] = e.id; o["rfid"] = e.rfid; o["name"] = e.name; o["type"] = e.type;
          o["status"] = e.status; o["message"] = e.message; o["date"] = e.date; o["time"] = e.time;
          o["known"] = e.known; o["attendanceMarked"] = e.marked;
          delivered = e.id;
        }
      }
    }
    d["lastId"] = baseline ? latest : delivered;
    d["latestId"] = latest;
    d["readerReady"] = Hardware::scanReady();
    d["readerState"] = Hardware::scanState();
    json(d);
  });

  server.on("/api/notifications", HTTP_GET, [] {
    if (!authed()) { error(401, "Login required"); return; }
    DynamicJsonDocument d(safeJsonCap(16384, 4096));
    d["ok"] = true;
    JsonArray a = d.createNestedArray("items");
    if (adminRole()) {
      for (auto& n : Data::notices) if (!n.done) { JsonObject o = a.createNestedObject(); o["id"] = n.id; o["message"] = n.message; }
    }
    d["count"] = a.size();
    json(d);
  });

  server.on("/api/notification/resolve", HTTP_POST, [] {
    if (!authed()) { error(401, "Login required"); return; }
    if (!adminRole()) { error(403, "Admin inbox only"); return; }
    auto d = body();
    uint32_t id = d["id"] | 0;
    bool changed = false;
    for (auto& n : Data::notices) if (n.id == id && !n.done) { n.done = true; n.clouded = false; changed = true; }
    if (changed) { Data::markDirty(false); Data::save(); Cloud::triggerSyncNow(); }
    ok("Resolved");
  });

  server.on("/api/notifications/resolve-all", HTTP_POST, [] {
    if (!authed()) { error(401, "Login required"); return; }
    if (!adminRole()) { error(403, "Admin inbox only"); return; }
    auto d = body(4096);
    bool selected = d["ids"].is<JsonArray>();
    uint16_t count = 0;
    for (auto& n : Data::notices) {
      bool match = !selected;
      if (selected) for (JsonVariant v : d["ids"].as<JsonArray>()) if ((uint32_t)(v | 0) == n.id) { match = true; break; }
      if (match && !n.done) { n.done = true; n.clouded = false; count++; }
    }
    if (count) { Data::markDirty(false); Data::save(); Cloud::triggerSyncNow(); }
    DynamicJsonDocument r(256);
    r["ok"] = true; r["resolved"] = count; r["message"] = "Seen notifications cleared";
    json(r);
  });

  server.on("/api/leaves", HTTP_GET, [] {
    if (!authed()) { error(401, "Login required"); return; }
    DynamicJsonDocument d(safeJsonCap(16384, 4096));
    d["ok"] = true;
    JsonArray a = d.createNestedArray("items");
    for (auto& l : Data::leaves) {
      JsonObject o = a.createNestedObject();
      o["id"] = l.id; o["rfid"] = l.rfid; o["student_id"] = l.rfid;
      o["name"] = l.name; o["from"] = l.from; o["to"] = l.to;
      o["reason"] = l.reason; o["status"] = l.status;
    }
    json(d);
  });

  server.on("/api/leaves/apply", HTTP_POST, [] {
    if (!authed()) { error(401, "Login required"); return; }
    auto d = body();
    String id = upper(jsonStr(d["rfid"], jsonStr(d["student_id"])));
    String from = jsonStr(d["from"]), to = jsonStr(d["to"]), reason = jsonStr(d["reason"]);
    Student* st = Data::student(id);
    if (!st || !validDate(from) || !validDate(to) || to < from || !reason.length()) { error(400, "Invalid leave request"); return; }
    if (Data::leaves.size() >= MAX_LEAVES) Data::leaves.erase(Data::leaves.begin());
    Leave l;
    l.id = Data::nextLeave++;
    l.rfid = st->rfid;
    l.name = st->name;
    l.from = from;
    l.to = to;
    l.reason = reason;
    l.clouded = false;
    Data::leaves.push_back(l);
    Data::addNotice(st->name + " applied for leave");
    Data::markDirty(false);
    Data::save();
    Cloud::triggerSyncNow();
    ok("Leave submitted");
  });

  auto decideLeaveHandler = []() {
    if (!authed()) { error(401, "Login required"); return; }
    auto d = body();
    uint32_t id = d["id"] | 0;
    String action = lower(jsonStr(d["action"], jsonStr(d["status"], "approve")));
    bool found = false;
    for (auto& l : Data::leaves) {
      if (l.id == id) {
        l.status = (action == "approve" || action == "approved") ? "approved" : "rejected";
        l.clouded = false;
        found = true;
        if (l.status == "approved") {
          String day = l.from;
          for (int guard = 0; guard < 120 && day <= l.to; guard++) {
            Data::putRecord(l.rfid, day, AStatus::LEAVE, "leave-approved");
            day = Data::nextDateStr(day);
          }
        }
        Cloud::rpcApproveLeave(l);
      }
    }
    if (!found) { error(404, "Leave not found"); return; }
    Data::recountAll();
    Data::markDirty(false);
    Data::save();
    Cloud::triggerSyncNow();
    ok("Leave decision saved and synced to Supabase");
  };

  server.on("/api/leaves/decide", HTTP_POST, decideLeaveHandler);
  server.on("/api/leave/approve", HTTP_POST, decideLeaveHandler);

