  auto addHolidayHandler = []() {
    if (!authed()) { error(401, "Login required"); return; }
    auto d = body();
    String day = jsonStr(d["date"]);
    String name = jsonStr(d["name"], "Holiday");
    if (!validDate(day)) { error(400, "Invalid date"); return; }
    if (std::find(Data::holidays.begin(), Data::holidays.end(), day) == Data::holidays.end()) Data::holidays.push_back(day);
    Data::deletedHolidays.erase(std::remove(Data::deletedHolidays.begin(), Data::deletedHolidays.end(), day), Data::deletedHolidays.end());
    for (size_t i = 0; i < Data::records.size(); ) {
      if (Data::records[i].date == day && Data::records[i].source == "automatic") Data::records.erase(Data::records.begin() + i);
      else i++;
    }
    Data::recountAll();
    Data::markDirty(false);
    Data::save();
    Hardware::announceSave("Holiday");
    Cloud::rpcCreateHoliday(day, name);
    Cloud::queueSettingsPush();
    Cloud::triggerSyncNow();
    ok("Holiday added");
  };

  server.on("/api/holidays", HTTP_POST, addHolidayHandler);
  server.on("/api/holiday", HTTP_POST, addHolidayHandler);

  server.on("/api/holiday/delete", HTTP_POST, [] {
    if (!authed()) { error(401, "Login required"); return; }
    auto d = body();
    String day = jsonStr(d["date"]);
    Data::holidays.erase(std::remove(Data::holidays.begin(), Data::holidays.end(), day), Data::holidays.end());
    if (std::find(Data::deletedHolidays.begin(), Data::deletedHolidays.end(), day) == Data::deletedHolidays.end()) {
      if (Data::deletedHolidays.size() >= MAX_TOMBSTONES) Data::deletedHolidays.erase(Data::deletedHolidays.begin());
      Data::deletedHolidays.push_back(day);
    }
    Data::recountAll();
    Data::markDirty(false);
    Data::save();
    Hardware::announceSave("Holiday");
    Cloud::rpcDeleteHoliday(day);
    Cloud::queueSettingsPush();
    Cloud::triggerSyncNow();
    ok("Holiday removed");
  });

