    d["lastSuccess"] = Cloud::lastSuccess;
    d["databaseHost"] = ASTRO_SUPABASE_HOST;
    d["deviceCode"] = ASTRO_DEVICE_CODE;
    d["automatic"] = true;
    int pr = 0, pp = 0, pe = 0, ps = 0, pl = 0, pn = 0;
    for (auto& r : Data::records) if (!r.clouded) pr++;
    for (auto& x : Data::periodMarks) if (!x.clouded) pp++;
    for (auto& e : Data::events) if (!e.clouded) pe++;
    for (auto& x : Data::students) if (!x.clouded) ps++;
    for (auto& x : Data::leaves) if (!x.clouded) pl++;
    for (auto& x : Data::notices) if (!x.clouded) pn++;
    d["pendingStudents"] = ps;
    d["pendingLeaves"] = pl;
    d["pendingNotifications"] = pn;
    d["pendingDailyRecords"] = pr;
