    d["studentCloudLoginLastSuccess"] = Cloud::studentAuthLastSuccess;
    d["autoRepairing"] = (Cloud::state == Cloud::State::BACKOFF || Cloud::state == Cloud::State::DEGRADED);
    d["requiresRulesDeployment"] = false;
