    bool del = (int32_t)(Hardware::deleteUntil - n) > 0;
    bool adm = (int32_t)(Hardware::adminUntil - n) > 0;
    d["ok"] = true;
    d["phase"] = del ? "delete" : (adm ? "armed" : "idle");
    d["left"] = del ? (Hardware::deleteUntil - n + 999) / 1000 : (adm ? (Hardware::adminUntil - n + 999) / 1000 : 0);
