  auto getMessagesHandler = []() {
    if (!authed()) { error(401, "Login required"); return; }
    String who = upper(server.arg("rfid"));
    if (!who.length()) who = upper(server.arg("to"));
    String r, u;
    if (resolveToken(extractReqToken(), r, u) && r == "student" && u.length() && !who.length()) who = u;
    DynamicJsonDocument d(safeJsonCap(16384, 4096));
    d["ok"] = true;
    JsonArray a = d.createNestedArray("items");
    for (auto it = Data::dms.rbegin(); it != Data::dms.rend(); ++it) {
      if (who.length() && it->rfid != who) continue;
      JsonObject o = a.createNestedObject();
      o["id"] = it->id; o["rfid"] = it->rfid; o["to"] = it->rfid;
      o["name"] = it->name; o["from"] = it->from; o["subject"] = it->subject;
      o["body"] = it->body; o["text"] = it->body; o["date"] = it->date;
      o["time"] = it->time; o["read"] = it->read;
    }
    json(d);
  };

  auto postMessageHandler = []() {
    if (!authed()) { error(401, "Login required"); return; }
    auto d = body(8192);
    String subj = jsonStr(d["subject"]), txt = jsonStr(d["body"], jsonStr(d["text"])), msg = jsonStr(d["message"]);
    subj.trim(); txt.trim(); msg.trim();
    if (!subj.length() && !txt.length() && msg.length()) {
      int nl = msg.indexOf("\n\n");
      if (nl > 0) { subj = msg.substring(0, nl); txt = msg.substring(nl + 2); }
      else { subj = "Message"; txt = msg; }
    } else if (!msg.length()) {
      msg = subj.length() ? (subj + "\n\n" + txt) : txt;
    }

    // Collect recipients from either d["rfids"] array or d["to"] string/array, rejecting null/undefined
    std::vector<String> recipKeys;
    if (d["rfids"].is<JsonArray>()) {
      for (JsonVariant v : d["rfids"].as<JsonArray>()) {
        String k = v.as<String>(); k.trim();
        if (k.length() && k != "undefined" && k != "null") recipKeys.push_back(k);
      }
    } else if (d["to"].is<JsonArray>()) {
      for (JsonVariant v : d["to"].as<JsonArray>()) {
        String k = v.as<String>(); k.trim();
        if (k.length() && k != "undefined" && k != "null") recipKeys.push_back(k);
      }
    } else if (d.containsKey("to")) {
      String toStr = jsonStr(d["to"]);
      toStr.trim();
      if (toStr.length() && toStr != "undefined" && toStr != "null") {
        int startIdx = 0;
        while (startIdx < (int)toStr.length()) {
          int comma = toStr.indexOf(',', startIdx);
          String part = (comma < 0) ? toStr.substring(startIdx) : toStr.substring(startIdx, comma);
          part.trim();
          if (part.length() && part != "undefined" && part != "null") recipKeys.push_back(part);
          if (comma < 0) break;
          startIdx = comma + 1;
        }
      }
    }

    if (!txt.length() || recipKeys.empty()) { error(400, "Recipients ('to') and message text are required"); return; }
    if (!subj.length()) subj = "Message";
    if (subj.length() > 120) subj = subj.substring(0, 120);
    if (txt.length() > 600) txt = txt.substring(0, 600);
    int stored = 0;
    uint32_t lastCreatedId = 0;
    for (const String& key : recipKeys) {
      Student* s = Data::student(key);
      if (!s) s = Data::loginStudent(key);
      if (!s) continue;
      Dm m;
      m.id = Data::nextDm++;
      lastCreatedId = m.id;
      m.rfid = s->rfid;
      m.name = s->name;
      m.from = jsonStr(d["from"], adminRole() ? "Admin" : "Student");
      m.subject = subj;
      m.body = txt;
      m.date = dateNow();
      m.time = timeNow().substring(0, 5);
      m.read = false;
      m.clouded = false;
      Data::dms.push_back(m);
      Data::trimDms(MAX_DMS);
      Cloud::rpcSendMessage(m);
      stored++;
    }
    if (!stored) { error(400, "No valid recipients found"); return; }
    Data::markDirty(false);
    Data::save();
    Cloud::triggerSyncNow();
    DynamicJsonDocument r(512);
    r["ok"] = true; r["id"] = lastCreatedId; r["stored"] = stored; r["queued"] = 0; r["message"] = "Direct message sent";
    json(r, 200);
  };

  server.on("/api/dm", HTTP_GET, getMessagesHandler);
