  // Admin Device Check endpoints (both /api/device-check/* and /api/lcd/print, /api/rfid/arm, /api/rfid/result, /api/fp/status)
  auto lcdPrintHandler = []() {
    if (!authed()) { error(401, "Login required"); return; }
    if (!adminRole()) { error(403, "Admin access required"); return; }
    auto d = body(512);
    String txt = jsonStr(d["text"]);
    txt.trim();
    if (!txt.length()) { error(400, "Text required"); return; }
    String l1 = txt, l2 = "";
    if (txt.length() > 16) {
      int sp = txt.lastIndexOf(' ', 16);
      if (sp > 0) {
        l1 = txt.substring(0, sp);
        l2 = txt.substring(sp + 1, min((unsigned int)txt.length(), (unsigned int)(sp + 17)));
      } else {
        l1 = txt.substring(0, 16);
        l2 = txt.substring(16, min((unsigned int)txt.length(), 32U));
      }
    }
    Hardware::line(0, l1, true);
    Hardware::line(1, l2, true);
    Hardware::showResult(l1, l2, 8000);
    Hardware::beep(60, 2400);
    Hardware::event("LCD-CHK", "LCD Check", "device-check", "OK", "LCD printed: " + txt, true, false);
    DynamicJsonDocument r(512);
    r["ok"] = true; r["l1"] = l1; r["l2"] = l2; r["lcdOk"] = Hardware::lcdOk;
    json(r);
  };

